// This file is generated by AI.

// 最近项目 (纯函数): 列表维护、搜索、封面路径与时间显示。

import { baseName } from './paths';

/** 最近项目记录。 */
export interface RecentProject {
  path: string;
  /** `config.txt` 里的 `Game_name` (打开/刷新时读到的那一份) */
  name?: string;
  /** `config.txt` 里的 `Description` */
  description?: string;
  /** `config.txt` 里的 `Title_img` (仅文件名, 位于 game/background 下) */
  titleImg?: string;
  /** 上次打开时间 (ms) */
  lastOpened: number;
}

/** 最近项目元数据 (从 config.txt 读到, 用于回填列表) */
export interface RecentProjectMeta {
  name?: string;
  description?: string;
  titleImg?: string;
}

/** 列表上限: 有了搜索, 可以比过去 (10 条) 多留一些。 */
export const RECENT_PROJECT_LIMIT = 20;

/**
 * 把持久化里读到的东西整理成最近项目列表。
 *
 * 兼容两种历史形状: v0.5.1 及以前的 `string[]` (只有路径), 以及现在的对象数组。
 * 无法识别的条目直接丢弃 —— 列表里混进 `undefined` 会在渲染时才炸。
 */
export function normalizeRecentProjects(raw: unknown): RecentProject[] {
  if (!Array.isArray(raw)) return [];
  const now = Date.now();
  const list: RecentProject[] = [];
  const seen = new Set<string>();

  raw.forEach((item, index) => {
    const normalized = normalizeEntry(item, now - index);
    if (!normalized) return;
    const key = normalized.path.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    list.push(normalized);
  });

  return list.slice(0, RECENT_PROJECT_LIMIT);
}

function normalizeEntry(item: unknown, fallbackTime: number): RecentProject | null {
  if (typeof item === 'string') {
    const path = item.trim();
    return path ? { path, lastOpened: fallbackTime } : null;
  }
  if (!item || typeof item !== 'object') return null;
  const record = item as Partial<RecentProject>;
  if (typeof record.path !== 'string' || !record.path.trim()) return null;
  return {
    path: record.path,
    name: nonEmpty(record.name),
    description: nonEmpty(record.description),
    titleImg: nonEmpty(record.titleImg),
    lastOpened: Number.isFinite(record.lastOpened) ? Number(record.lastOpened) : fallbackTime,
  };
}

function nonEmpty(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
}

/** 按最近打开时间倒序。 */
export function sortRecentProjects(list: RecentProject[]): RecentProject[] {
  return [...list].sort((a, b) => b.lastOpened - a.lastOpened);
}

/**
 * 搜索: 名称与路径都参与匹配。
 *
 * 路径虽然不显示, 但要能被搜到 —— 用户记得住的往往是目录名 (比如 `lesson`),
 * 而 `Game_name` 可能是个中文标题。简介**不**参与: 卡片上不显示它, 靠它命中的结果
 * 会让人看不出为什么匹配。
 *
 * 泛型是为了让调用方拿回自己的视图类型 (卡片需要 `available` 这类仅存在于界面上的字段)。
 */
export function filterRecentProjects<T extends { name?: string; path: string }>(list: T[], query: string): T[] {
  const needle = query.trim().toLowerCase();
  if (!needle) return list;
  return list.filter((project) => [project.name, project.path].some((field) => field?.toLowerCase().includes(needle)));
}

/**
 * 打开项目时更新列表: 提到最前、合并新读到的元数据。
 *
 * 元数据缺省的字段**保留原值**: 读 config.txt 失败时不该把已有的项目名抹掉。
 */
export function upsertRecentProject(
  list: RecentProject[],
  path: string,
  meta: RecentProjectMeta = {}
): RecentProject[] {
  const previous = list.find((item) => item.path.toLowerCase() === path.toLowerCase());
  const next: RecentProject = {
    path,
    name: meta.name ?? previous?.name,
    description: meta.description ?? previous?.description,
    titleImg: meta.titleImg ?? previous?.titleImg,
    lastOpened: Date.now(),
  };
  return [next, ...list.filter((item) => item.path.toLowerCase() !== path.toLowerCase())].slice(
    0,
    RECENT_PROJECT_LIMIT
  );
}

/** 从列表中移除一项 (不动磁盘)。 */
export function removeRecentProject(list: RecentProject[], path: string): RecentProject[] {
  return list.filter((item) => item.path.toLowerCase() !== path.toLowerCase());
}

/** 列表里显示的名字: 优先 config.txt 里的游戏名, 退回到目录名。 */
export function projectDisplayName(project: RecentProject): string {
  return project.name?.trim() || baseName(project.path);
}

/** 标题背景图在项目内的相对路径 (预览服务器的站点根即项目根)。 */
export function coverRelativePath(titleImg: string | undefined): string | null {
  const name = titleImg?.trim();
  // 配置里允许写子目录, 但绝不允许跳出 game/background
  if (!name || name.includes('..')) return null;
  return `game/background/${name.replace(/\\/g, '/').replace(/^\/+/, '')}`;
}

/** 人类可读的相对时间 (列表里显示"上次打开")。 */
export function formatRelativeTime(timestamp: number, now = Date.now()): string {
  const diff = now - timestamp;
  if (!Number.isFinite(diff)) return '未知时间';
  if (diff < 60_000) return '刚刚';
  const minutes = Math.floor(diff / 60_000);
  if (minutes < 60) return `${minutes} 分钟前`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours} 小时前`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `${days} 天前`;
  const date = new Date(timestamp);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}
